<template>
  <div class="page plugin-page">
    <header class="page-heading">
      <div><span class="eyebrow">PLUGIN CONTROL PLANE</span><h1>Dinq Discover 运维</h1><p>查看 Dinq 工具、Skills、场景、Worker 加载状态与真实执行链路。</p></div>
      <div class="heading-actions"><button class="secondary-button" :disabled="diagnosing" @click="diagnose">{{ diagnosing ? '诊断中…' : '执行只读诊断' }}</button><button class="secondary-button" :disabled="loading" @click="load">{{ loading ? '刷新中…' : '刷新' }}</button></div>
    </header>
    <div v-if="error" class="notice error-notice">{{ error }}</div>
    <template v-else-if="overview">
      <section class="release-strip panel"><div><span class="eyebrow">ACTIVE RELEASE</span><strong>{{ overview.release.name }}</strong><small>{{ overview.release.plugin_id }} · v{{ overview.release.version }}</small></div><div><span>组件</span><strong>{{ overview.components.length }}</strong></div><div><span>健康 Worker</span><strong>{{ overview.worker_summary.healthy_loaded }}/{{ overview.worker_summary.total }}</strong></div><div><span>24h 成功率</span><strong>{{ percent(overview.metrics.success_rate) }}</strong></div><div><span>P95</span><strong>{{ latency(overview.metrics.p95_duration_ms) }}</strong></div></section>
      <nav class="plugin-tabs"><button v-for="item in tabs" :key="item.id" :class="{ active: tab === item.id }" @click="tab = item.id">{{ item.label }} <small>{{ item.count }}</small></button></nav>
      <section v-if="tab === 'overview'" class="plugin-grid">
        <article class="panel"><span class="eyebrow">RELEASE</span><h2>{{ overview.release.description }}</h2><dl><dt>Distribution</dt><dd>{{ overview.release.distribution_name || '—' }}</dd><dt>Build</dt><dd>{{ overview.release.build_digest || '未声明' }}</dd></dl></article>
        <article class="panel"><span class="eyebrow">DEPENDENCIES</span><div class="dependency-list"><div v-for="item in dependencies" :key="String(item.id)"><i /> <strong>{{ item.name }}</strong><small>{{ item.kind }} · {{ item.required ? 'required' : 'optional' }}</small></div></div></article>
        <article class="panel wide"><span class="eyebrow">COMPONENT METRICS</span><div class="metric-table"><div v-for="item in overview.metrics.by_component" :key="item.capability_id"><code>{{ item.capability_id }}</code><span>{{ item.total }} calls</span><span>{{ item.failed }} failed</span><span>P95 {{ latency(item.p95_duration_ms) }}</span></div><p v-if="!overview.metrics.by_component.length" class="muted">暂无 Dinq 调用记录。</p></div></article>
      </section>
      <section v-else-if="tab === 'components'" class="components-workspace">
        <div class="component-grid"><article v-for="item in overview.components" :key="item.component_id" class="panel component-card" :class="{ selected: selectedComponent?.component_id === item.component_id }"><span class="kind">{{ item.component_type }}</span><h2>{{ item.name }}</h2><code>{{ item.reference_id }} · v{{ item.reference_version }}</code><p>{{ item.description || '无额外说明' }}</p><small v-if="item.metadata.adapter">{{ item.metadata.adapter }}</small><button v-if="configurable(item)" class="secondary-button" @click="openSettings(item)">配置与启停</button><button v-else-if="item.component_type === 'scenario'" class="secondary-button" @click="openScenario(item)">编辑并测试</button></article></div>
        <aside v-if="selectedComponent && settings" class="panel settings-panel"><div class="settings-heading"><div><span class="eyebrow">RUNTIME SETTINGS</span><h2>{{ selectedComponent.name }}</h2><small>{{ selectedComponent.reference_id }} · 所有 Worker 将在下一次调用读取此配置</small></div><button class="secondary-button" @click="closeSettings">关闭</button></div><label class="switch-row"><input v-model="settings.enabled" type="checkbox" /><span><strong>启用组件</strong><small>关闭后 Agent 不再获得此能力，新的调用会被拒绝。</small></span></label><label class="config-field"><span>运行时配置（JSON）</span><textarea v-model="settingsText" rows="13" spellcheck="false" /></label><details><summary>配置 Schema</summary><pre>{{ pretty(settings.configuration_schema) }}</pre></details><p class="settings-note">只可配置非敏感运行参数。API Key、Token、密码必须留在服务器密钥环境中。</p><div class="settings-actions"><button class="secondary-button" :disabled="settingsSaving" @click="resetSettings">恢复</button><button class="primary-button" :disabled="settingsSaving" @click="saveSettings">{{ settingsSaving ? '保存中…' : '保存并热加载' }}</button></div></aside>
      </section>
      <section v-else-if="tab === 'topology'" class="panel topology"><span class="eyebrow">EXECUTION RELATIONSHIPS</span><div v-if="topology" class="topology-list"><article v-for="node in topology.nodes" :key="node.id"><strong>{{ node.label }}</strong><small>{{ node.kind }}</small><p>{{ links(node.id).join(' · ') || '无下游关联' }}</p></article></div><p v-else class="muted">正在读取关联图…</p></section>
      <section v-else-if="tab === 'health'" class="health-grid"><article v-for="item in health?.checks" :key="item.name" class="panel"><span :class="['status-dot', item.status]" /><span class="eyebrow">{{ item.name }}</span><h2>{{ item.status }}</h2><p>{{ item.summary }}</p></article></section>
      <section v-else class="panel invocation-list"><span class="eyebrow">RECENT INVOCATIONS</span><article v-for="item in invocations" :key="item.invocation_id"><div><code>{{ item.capability_id }}</code><small>{{ item.invocation_id }} · {{ formatDate(item.created_at) }}</small></div><span :class="['status-badge', item.status]">{{ item.status }}</span><button class="secondary-button" @click="openRun(item.run_id)">查看 Run</button></article><p v-if="!invocations.length" class="muted">暂无调用记录。</p></section>
    </template>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { getPlugin, getPluginHealth, getPluginInvocations, getPluginTopology, runPluginDiagnostics, type PluginComponent, type PluginHealth, type PluginInvocation, type PluginOverview, type PluginTopology } from '../api/plugins'
import { getCapabilityRuntimeSettings, saveCapabilityRuntimeSettings, type CapabilityRuntimeSettings } from '../api/admin'

const pluginId = 'dinq.discover'; const router = useRouter(); const loading = ref(false); const error = ref(''); const tab = ref('overview')
const overview = ref<PluginOverview | null>(null); const topology = ref<PluginTopology | null>(null); const health = ref<PluginHealth | null>(null); const invocations = ref<PluginInvocation[]>([]); const diagnosing = ref(false)
const selectedComponent = ref<PluginComponent | null>(null); const settings = ref<CapabilityRuntimeSettings | null>(null); const settingsText = ref('{}'); const savedSettingsText = ref('{}'); const settingsSaving = ref(false)
const tabs = computed(() => [{ id: 'overview', label: '概览', count: '' }, { id: 'components', label: '组件', count: overview.value?.components.length || 0 }, { id: 'topology', label: '关联图', count: topology.value?.edges.length || 0 }, { id: 'health', label: '健康', count: health.value?.checks.length || 0 }, { id: 'invocations', label: '调用', count: invocations.value.length }])
const dependencies = computed(() => overview.value?.release.manifest.dependencies || [])
function percent(value: number) { return `${Math.round(value * 100)}%` }; function latency(value: number | null) { return value == null ? '—' : `${Math.round(value)} ms` }; function formatDate(value: string) { return new Date(value).toLocaleString('zh-CN') }
function pretty(value: unknown) { return JSON.stringify(value || {}, null, 2) }; function configurable(item: PluginComponent) { return item.component_type === 'tool' || item.component_type === 'skill' }
function links(id: string) { return (topology.value?.edges || []).filter((item) => item.source === id).map((item) => topology.value?.nodes.find((node) => node.id === item.target)?.label || item.target) }
async function load() { loading.value = true; error.value = ''; try { const [item, graph, checks, recent] = await Promise.all([getPlugin(pluginId), getPluginTopology(pluginId), getPluginHealth(pluginId), getPluginInvocations(pluginId)]); overview.value = item; topology.value = graph; health.value = checks; invocations.value = recent.items } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取 Dinq 插件状态失败' } finally { loading.value = false } }
async function diagnose() { diagnosing.value = true; error.value = ''; try { await runPluginDiagnostics(pluginId); await load(); tab.value = 'health' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Dinq 诊断失败' } finally { diagnosing.value = false } }
async function openSettings(item: PluginComponent) { selectedComponent.value = item; settings.value = null; error.value = ''; try { const value = await getCapabilityRuntimeSettings(item.reference_id); settings.value = value; settingsText.value = pretty(value.configuration); savedSettingsText.value = settingsText.value } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取组件配置失败' } }
function closeSettings() { selectedComponent.value = null; settings.value = null; settingsText.value = '{}' }; function resetSettings() { settingsText.value = savedSettingsText.value }
async function saveSettings() { if (!selectedComponent.value || !settings.value) return; let configuration: Record<string, unknown>; try { const parsed = JSON.parse(settingsText.value); if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error('配置必须是 JSON 对象'); configuration = parsed as Record<string, unknown> } catch (cause) { error.value = cause instanceof Error ? cause.message : '配置 JSON 无效'; return } settingsSaving.value = true; error.value = ''; try { const value = await saveCapabilityRuntimeSettings(selectedComponent.value.reference_id, { enabled: settings.value.enabled, configuration }); settings.value = { ...settings.value, ...value, configuration_schema: settings.value.configuration_schema }; settingsText.value = pretty(value.configuration); savedSettingsText.value = settingsText.value } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存组件配置失败' } finally { settingsSaving.value = false } }
function openRun(runId: string) { void router.push({ path: '/runs', query: { run: runId } }) }
function openScenario(item: PluginComponent) { void router.push({ path: '/scenarios', query: { scenario: item.reference_id, version: item.reference_version } }) }
watch(tab, (value) => { if (value !== 'overview' && !topology.value) void load() }); onMounted(load)
</script>

<style scoped>
.plugin-page{display:flex;flex-direction:column;gap:16px}.release-strip{display:grid;grid-template-columns:minmax(220px,2fr) repeat(4,minmax(100px,1fr));gap:18px;align-items:center;padding:18px 22px}.release-strip>div{display:flex;flex-direction:column;gap:4px}.release-strip strong{color:var(--text-strong);font-size:20px}.release-strip small,.release-strip span,.eyebrow,.muted{color:var(--text-muted);font-size:11px}.plugin-tabs{display:flex;gap:8px;border-bottom:1px solid var(--border)}.plugin-tabs button{padding:10px 13px;border:0;border-bottom:2px solid transparent;color:var(--text-muted);background:transparent;cursor:pointer}.plugin-tabs button.active{color:var(--accent);border-color:var(--accent)}.plugin-tabs small{margin-left:4px}.plugin-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{padding:18px}.panel h2{margin:8px 0 12px;color:var(--text-strong);font-size:16px}.wide{grid-column:1/-1}dl{display:grid;grid-template-columns:120px 1fr;gap:8px;margin:0;font-size:12px}dt{color:var(--text-muted)}dd{margin:0;overflow-wrap:anywhere}.dependency-list,.metric-table,.topology-list,.invocation-list{display:grid;gap:8px}.dependency-list>div,.metric-table>div,.topology-list article,.invocation-list article{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid var(--border);border-radius:8px}.dependency-list small,.topology-list small,.invocation-list small{color:var(--text-muted)}.dependency-list i{width:7px;height:7px;border-radius:50%;background:var(--success)}.metric-table span{margin-left:auto;color:var(--text-muted);font-size:11px}.components-workspace{display:grid;grid-template-columns:minmax(0,1fr) 390px;gap:16px;align-items:start}.component-grid,.health-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.component-card{display:flex;min-height:155px;flex-direction:column;align-items:flex-start}.component-card.selected{border-color:var(--accent-border)}.component-card .secondary-button{margin-top:auto}.component-card .kind{color:var(--accent);font:10px var(--font-mono);text-transform:uppercase}.component-card code{color:var(--text-muted);font-size:10px;overflow-wrap:anywhere}.component-card p{color:var(--text-muted);font-size:12px}.settings-panel{position:sticky;top:16px}.settings-heading{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.settings-heading h2{margin:5px 0}.settings-heading small,.settings-note,.config-field span{color:var(--text-muted);font-size:10px}.switch-row{display:flex;gap:10px;align-items:flex-start;margin:16px 0}.switch-row span{display:grid;gap:3px}.switch-row strong{font-size:12px;color:var(--text-strong)}.config-field{display:grid;gap:7px}.config-field textarea{width:100%;padding:10px;color:var(--text);background:var(--input);border:1px solid var(--border-strong);border-radius:9px;font:11px var(--font-mono);line-height:1.55}.settings-panel details{margin-top:12px;color:var(--text-muted);font-size:11px}.settings-panel pre{overflow:auto;padding:10px;background:var(--surface-raised);border:1px solid var(--border);border-radius:8px;font-size:10px}.settings-note{line-height:1.6}.settings-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}.topology-list article{display:grid;grid-template-columns:220px 100px 1fr}.topology-list p{margin:0;color:var(--text-muted);font-size:12px}.status-dot{display:block;width:9px;height:9px;border-radius:50%;background:var(--warning)}.status-dot.healthy{background:var(--success)}.status-dot.failed{background:var(--danger)}.invocation-list article>div{display:flex;min-width:0;flex:1;flex-direction:column;gap:4px}.invocation-list code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.status-badge{margin-left:auto}@media(max-width:1100px){.components-workspace{grid-template-columns:1fr}.settings-panel{position:static}.release-strip,.component-grid,.health-grid{grid-template-columns:1fr 1fr}.plugin-grid{grid-template-columns:1fr}.topology-list article{grid-template-columns:1fr}}@media(max-width:600px){.release-strip,.component-grid,.health-grid{grid-template-columns:1fr}.metric-table>div{align-items:flex-start;flex-direction:column}.metric-table span{margin-left:0}}
</style>
